divmod:
: divmod-loop
  (forall ρ; ρ a:Int b:Int q:Int -- ρ q2:Int r:Int)
  locals { a b q } {
    a b prim <
    [ q a ]
    [
      a b prim -
      b
      q 1 prim +
      divmod-loop
    ]
    if
  };

: main
  (forall ρ; ρ a:Int b:Int -- ρ q:Int r:Int)
  0 divmod-loop;

is-prime:
: true-val
  (forall ρ; ρ -- ρ b:Bool)
  0 0 prim =;

: false-val
  (forall ρ; ρ -- ρ b:Bool)
  1 0 prim =;

: remainder
  (forall ρ; ρ a:Int b:Int -- ρ r:Int)
  locals { a b } {
    a b prim <
    [ a ]
    [ a b prim - b remainder ]
    if
  };

: trial
  (forall ρ; ρ n:Int d:Int -- ρ result:Bool)
  locals { n d } {
    n d d prim * prim <
    [ true-val ]
    [
      n d remainder 0 prim =
      [ false-val ]
      [ n d 1 prim + trial ]
      if
    ]
    if
  };

: main
  (forall ρ; ρ n:Int -- ρ result:Bool)
  locals { n } {
    n 2 prim <
    [ false-val ]
    [ n 2 trial ]
    if
  };

digit-sum:
: divmod10-loop
  (forall ρ; ρ a:Int q:Int -- ρ q2:Int r:Int)
  locals { a q } {
    a 10 prim <
    [ q a ]
    [
      a 10 prim -
      q 1 prim +
      divmod10-loop
    ]
    if
  };

: digitsum-loop
  (forall ρ; ρ n:Int acc:Int -- ρ result:Int)
  locals { n acc } {
    n 0 prim =
    [ acc ]
    [
      n 0 divmod10-loop
      acc
      prim +
      digitsum-loop
    ]
    if
  };

: main
  (forall ρ; ρ n:Int -- ρ r:Int)
  0 digitsum-loop;

lcm:
: remainder
  (forall ρ; ρ a:Int b:Int -- ρ r:Int)
  locals { a b } {
    a b prim <
    [ a ]
    [ a b prim - b remainder ]
    if
  };

: gcd
  (forall ρ; ρ a:Int b:Int -- ρ g:Int)
  locals { a b } {
    b 0 prim =
    [ a ]
    [ b a b remainder gcd ]
    if
  };

: quotient-loop
  (forall ρ; ρ a:Int b:Int q:Int -- ρ result:Int)
  locals { a b q } {
    a b prim <
    [ q ]
    [ a b prim - b q 1 prim + quotient-loop ]
    if
  };

: quotient
  (forall ρ; ρ a:Int b:Int -- ρ q:Int)
  0 quotient-loop;

: main
  (forall ρ; ρ a:Int b:Int -- ρ r:Int)
  locals { a b } {
    a b gcd
    a
    swap
    quotient
    b
    prim *
  };
